export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;

/**
 * The spec keeps intermediate amounts as exact fractions and rounds only the
 * final amount. Binary floating point cannot do that: `100 * 1.1` is
 * 110.00000000000001, which rounds *up* to 111 instead of 110.
 *
 * So percentages are applied as integer rationals — multiply by the numerator
 * first, divide by the denominator last — and money is carried in hundredths
 * of a G. Both operands of every product stay integral, so no drift accrues.
 */
const SUBUNITS_PER_G = 100;
const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);

/** A percentage as an exact rational, e.g. +10 % is { num: 110, den: 100 }. */
interface Rate {
  num: number;
  den: number;
}

const FIRST_INSURANCE_SURCHARGE: Rate = { num: 110, den: 100 };

const applyRate = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;

/** Premiums round up — in the MHPCO's favour. */
const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);

const basePremiumOf = (item: Item): number => {
  return item.type === "sword" ? 100 : 0;
};

const quotePremium = (items: Item[]): number => {
  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const surcharged = applyRate(toSubunits(policyBase), FIRST_INSURANCE_SURCHARGE);

  return toPremiumGold(surcharged + toSubunits(PROCESSING_FEE));
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
};

