import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums for single main items ---
  it("quotes an empty item list at 5 G (processing fee only)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("quotes a plain sword at 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes a plain amulet at 71 G (60 base + 6 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("quotes a plain staff at 93 G (80 base + 8 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("quotes a plain potion at 49 G (40 base + 4 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Quote: components and the building block of 3 alike components ---
  it("prices 2 runes at 50 G base premium (no block)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    // 50 base + 5 first insurance + 5 fee
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("prices 3 runes at 60 G base premium (block applies)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });

    // 60 base (block) + 6 first insurance + 5 fee
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("prices 4 runes at 100 G base premium (no block — block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    // 100 base (no block) + 10 first insurance + 5 fee
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("prices 7 runes at 175 G base premium (no block — block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
    });

    // 175 base + 17.5 first insurance = 192.5, + 5 fee = 197.5, rounded up
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });

  // --- Quote: "alike" means exactly the same component type (❓) ---
  it("prices 2 runes + 1 moonstone at 75 G base premium (no block: different types)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }] },
      ],
    });

    // 75 base (no block — mixed types) + 7.5 first insurance = 82.5, + 5 fee = 87.5, rounded up
    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it.todo("prices 3 runes + 3 moonstones at 120 G base premium (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium");
  it.todo("adds a 30 % high-enchantment surcharge for enchantment exactly 5");
  it.todo("adds no high-enchantment surcharge for enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");

  // --- Quote: modifier scope on multi-item policies (❓) ---
  it.todo(
    "applies the curse surcharge only to the cursed item: cursed sword + plain amulet → 210 G before policy modifiers and fee",
  );

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10 % first insurance surcharge on the policy base premium");
  it.todo("applies a 15 % follow-up discount on the customer's second quote");

  // --- Quote: rounding in the MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed sword at 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");
  it.todo(
    "quotes a long-standing customer's second contract with a cursed enchantment-7 sword at 160 G (100 + 50 + 30 − 20 + 10 − 15 + 5)",
  );

  // --- Quote: errors ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick)");

  // --- Claim: standard reimbursement ---
  it.todo("pays 400 G for a steel enchantment-3 sword with 500 G damage (full reimbursement − 100 G deductible)");
  it.todo("pays 100 G for a damaged rune with 200 G damage (no enchantment or material clause)");

  // --- Claim: special clauses ---
  it.todo("pays 400 G for a steel enchantment-9 sword with 1000 G damage (50 % clause, then deductible)");
  it.todo("pays 700 G for a dragon-material enchantment-5 sword with 800 G damage (full reimbursement, then deductible)");
  it.todo("pays 400 G for a dragon-material enchantment-9 sword with 1000 G damage (50 % rule wins, then deductible)");
  it.todo("pays 400 G for a dragon-material sword with exactly enchantment 8 and 1000 G damage");

  // --- Claim: deductible per damage event ---
  it.todo("pays 600 G when a dragon attack damages a sword (500 G) and an amulet (300 G) — one deductible per damaged item");

  // --- Claim: rounding in the MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Claim: insurance sum and cap ---
  it.todo("reports remainingCap based on twice the insurance sum for a single sword policy (cap 2000 G)");
  it.todo("computes the insurance sum of a sword + amulet policy as 1600 G (cap 3200 G)");
  it.todo("bases the cap on the unmodified insurance value: a cursed sword still has cap 2000 G");
  it.todo("computes the insurance sum of a sword + 3 runes (a block) as 1750 G — the block discount affects only the premium");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays 1400 G on a first 1500 G claim against a sword policy, leaving 600 G of cap");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");

  // --- Claim: multiple items of the same type (❓) ---
  it.todo("insures two swords at an insurance sum of 2000 G (cap 4000 G)");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers");

  // --- Claim: errors ---
  it.todo("rejects a claim whose damage references an item not part of the policy (amulet damaged, only a sword insured)");
  it.todo("rejects a claim whose damage references an unknown item type");
  it.todo("rejects a claim containing a damage entry with a negative amount");

  // --- Multi-step scenarios ---
  it.todo("processes a scenario of a quote followed by a claim against that policy, returning results in step order");
});

