export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;

/**
 * The spec keeps intermediate amounts as exact fractions and rounds only the
 * final amount. Binary floating point cannot do that: `100 * 1.1` is
 * 110.00000000000001, which rounds *up* to 111 instead of 110.
 *
 * So percentages are applied as integer rationals — multiply by the numerator
 * first, divide by the denominator last — and money is carried in hundredths
 * of a G. Both operands of every product stay integral, so no drift accrues.
 */
const SUBUNITS_PER_G = 100;
const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);

/** A percentage as an exact rational, e.g. +10 % is { num: 110, den: 100 }. */
interface Rate {
  num: number;
  den: number;
}

const FIRST_INSURANCE_SURCHARGE: Rate = { num: 110, den: 100 };

const applyRate = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;

/** Premiums round up — in the MHPCO's favour. */
const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;

const COMPONENT_TYPES = ["rune", "moonstone"];

const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

/** Components are alike when they are of the very same type. */
const areAlike = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

/** Exactly this many alike components form a block, priced as one unit. */
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE && items.every(isComponent) && areAlike(items);

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item), 0);

/**
 * The policy base premium: every insured item's base premium, summed — except
 * that a block of alike components is priced as one unit instead.
 */
const policyBasePremiumOf = (items: Item[]): number =>
  formsComponentBlock(items) ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(items);

const quotePremium = (items: Item[]): number => {
  const policyBase = toSubunits(policyBasePremiumOf(items));

  return toPremiumGold(applyRate(policyBase, FIRST_INSURANCE_SURCHARGE) + toSubunits(PROCESSING_FEE));
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
};

