const itemSurchargesOf = (items: Item[]): number =>
  items.reduce(
    (total, item) =>
      total + (item.cursed ? applyRate(toSubunits(basePremiumOf(item)), CURSE_SURCHARGE) : 0),
    0,
  );

/**
 * Modifiers are additive amounts, each computed against its own base: item
 * surcharges against the affected item, policy-wide modifiers against the
 * policy base premium. The processing fee is added at the very end.
 */
const quotePremium = (items: Item[]): number => {
  const policyBase = toSubunits(policyBasePremiumOf(items));
  const policyModifiers = applyRate(policyBase, FIRST_INSURANCE_SURCHARGE);

  return toPremiumGold(
    policyBase + itemSurchargesOf(items) + policyModifiers + toSubunits(PROCESSING_FEE),
  );
};

