 * Steps are processed in order, since a step's result can depend on those
 * before it — a quote is discounted once the customer holds an earlier one.
 *
 * Each step both produces a result and hands on the standing the next step will
 * see, so that a step's effect on later steps lives with the step's own logic
 * rather than in loose accumulators advanced by hand here.
 */
export const runScenario = (scenario: Scenario): ScenarioResults => {
  const results: QuoteResult[] = [];
  let standing: CustomerStanding = { customer: scenario.customer, quotesSoFar: 0 };

  for (const step of scenario.steps) {
    const outcome = applyQuote(step, standing);
    results.push(outcome.result);
    standing = outcome.standing;
  }

  return { results };
};

