136	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
137	  sword: 1000,
138	  amulet: 600,
139	  staff: 800,
140	  potion: 400,
141	  rune: 250,
142	  moonstone: 250,
143	};
