/**
 * A claim reimburses each damaged item, less the deductible, and draws the
 * total down from the policy's remaining cap. A claim for more than the policy
 * has left pays out only what remains, so the cap never runs negative.
 */
const applyClaim = (step: ClaimStep, ledger: Ledger): StepOutcome => {
  const policy = assumePolicy(ledger, step.policy);
  const uncappedPayout = step.incident.damages.reduce(
    (total, damage) => total + reimbursementFor(damage, assumeDamagedItem(policy, damage)),
    0,
  );
  const payout = Math.min(uncappedPayout, policy.remainingCap);
  const remainingCap = policy.remainingCap - payout;

