 * the reimbursed share of the damage, less the deductible.
 *
 * A damage cannot be worth less than nothing. Were one allowed to, it would not
 * merely pay out negatively — it would *return* cap to the policy, letting a
 * later claim draw more than twice the insurance sum.
 */
const reimbursementFor = (damage: Damage, item: Item): number => {
  if (damage.amount < 0) {
    throw new ClaimOfficeError(`Damage amount cannot be negative: ${damage.amount}`);
  }

  return shareAmount(toSubunits(damage.amount), reimbursedShareOf(item)) - toSubunits(DEDUCTIBLE);
};

